-- part 31_coupon_holds.sql
/* Discount code limits two buyers at once cannot pass: a payment that starts with a limited code holds a place under the limit, the order turns it into the use, an abandoned payment gives it back or it expires after 35 minutes (lib/checkout/coupon-holds.ts). Server only. Source: supabase/migrations/20261004_coupon_holds.sql. Until it runs the checkout counts uses as before. */
CREATE TABLE IF NOT EXISTS public.coupon_holds ( coupon_id uuid NOT NULL REFERENCES public.coupons(id) ON DELETE CASCADE, holder text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (coupon_id, holder) );
ALTER TABLE public.coupon_holds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.coupon_holds FROM anon, authenticated;
/* Takes or refreshes a holder's place. The code's row is locked first, so two calls for one code run one after the other, and the second counts the first one's place. Expired places are cleared on the way. True when there is room (always, for a code with no limit), false when there is none. */
CREATE OR REPLACE FUNCTION public.hold_coupon_use(p_coupon_id uuid, p_holder text, p_seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE lim integer; used integer; others integer; BEGIN SELECT c.usage_limit, coalesce(c.usage_count, 0) INTO lim, used FROM public.coupons c WHERE c.id = p_coupon_id FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; DELETE FROM public.coupon_holds h WHERE h.coupon_id = p_coupon_id AND h.expires_at < now(); IF lim IS NULL THEN RETURN true; END IF; SELECT count(*) INTO others FROM public.coupon_holds h WHERE h.coupon_id = p_coupon_id AND h.holder <> p_holder; IF used + others >= lim THEN RETURN false; END IF; INSERT INTO public.coupon_holds (coupon_id, holder, expires_at) VALUES (p_coupon_id, p_holder, now() + make_interval(secs => greatest(60, least(coalesce(p_seconds, 2100), 86400)))) ON CONFLICT (coupon_id, holder) DO UPDATE SET expires_at = excluded.expires_at; RETURN true; END $$;
/* One use counted and the holder's place dropped, in one statement each, the code's row locked first as above. Counted whether or not the place was still there: the order exists. */
CREATE OR REPLACE FUNCTION public.use_coupon_hold(p_coupon_id uuid, p_holder text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN UPDATE public.coupons SET usage_count = coalesce(usage_count, 0) + 1 WHERE id = p_coupon_id; DELETE FROM public.coupon_holds WHERE coupon_id = p_coupon_id AND holder = p_holder; END $$;
/* A place given back: the payment it was for will not happen. */
CREATE OR REPLACE FUNCTION public.release_coupon_hold(p_coupon_id uuid, p_holder text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ DELETE FROM public.coupon_holds WHERE coupon_id = p_coupon_id AND holder = p_holder; $$;
/* Only the server holds, uses and gives back places. */
REVOKE ALL ON FUNCTION public.hold_coupon_use(uuid, text, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.hold_coupon_use(uuid, text, integer) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hold_coupon_use(uuid, text, integer) TO service_role;
REVOKE ALL ON FUNCTION public.use_coupon_hold(uuid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.use_coupon_hold(uuid, text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.use_coupon_hold(uuid, text) TO service_role;
REVOKE ALL ON FUNCTION public.release_coupon_hold(uuid, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.release_coupon_hold(uuid, text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.release_coupon_hold(uuid, text) TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.coupon_holds TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('31', '31_coupon_holds.sql', '571b0cc71956bf7525fa6ed294bfedd355c638d0100ad5c20eaf1005e536ca91') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 32_orders_keep_sales.sql
/* Sales kept when a product is deleted: orders carry their creator (filled from the product by a trigger, and for every order already there), deleting a product leaves its orders with no product instead of deleting them, a disputed payment can be written, and the all time line counts by the creator. Changes existing rows: fills orders.creator_id. Deletes nothing. Source: supabase/migrations/20261004_orders_keep_creator.sql. */
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS creator_id uuid;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_creator_id_fkey') THEN ALTER TABLE public.orders ADD CONSTRAINT orders_creator_id_fkey FOREIGN KEY (creator_id) REFERENCES public.creators(id) ON DELETE CASCADE NOT VALID; END IF; END $$;
UPDATE public.orders o SET creator_id = p.creator_id FROM public.products p WHERE p.id = o.product_id AND o.creator_id IS DISTINCT FROM p.creator_id;
CREATE OR REPLACE FUNCTION public.orders_fill_creator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF NEW.product_id IS NOT NULL THEN NEW.creator_id := (SELECT p.creator_id FROM public.products p WHERE p.id = NEW.product_id); END IF; RETURN NEW; END $fn$;
DROP TRIGGER IF EXISTS orders_fill_creator ON public.orders;
CREATE TRIGGER orders_fill_creator BEFORE INSERT OR UPDATE OF product_id, creator_id ON public.orders FOR EACH ROW EXECUTE FUNCTION public.orders_fill_creator();
CREATE INDEX IF NOT EXISTS idx_orders_creator_time_id ON public.orders (creator_id, created_at, id);
ALTER TABLE public.orders ALTER COLUMN product_id DROP NOT NULL;
DO $$ DECLARE c record; BEGIN FOR c IN SELECT con.conname FROM pg_constraint con WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'f' AND con.confrelid = 'public.products'::regclass AND con.confdeltype <> 'n' AND con.conkey = ARRAY[(SELECT a.attnum FROM pg_attribute a WHERE a.attrelid = 'public.orders'::regclass AND a.attname = 'product_id')] LOOP EXECUTE format('ALTER TABLE public.orders DROP CONSTRAINT %I', c.conname); END LOOP; IF NOT EXISTS (SELECT 1 FROM pg_constraint con WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'f' AND con.confrelid = 'public.products'::regclass AND con.confdeltype = 'n') THEN ALTER TABLE public.orders ADD CONSTRAINT orders_product_id_fkey FOREIGN KEY (product_id) REFERENCES public.products(id) ON DELETE SET NULL NOT VALID; END IF; END $$;
DO $$ DECLARE c record; BEGIN FOR c IN SELECT con.conname, pg_get_constraintdef(con.oid) AS def FROM pg_constraint con WHERE con.conrelid = 'public.orders'::regclass AND con.contype = 'c' AND pg_get_constraintdef(con.oid) ~ '^CHECK \(\(status = ANY \(ARRAY\[' AND pg_get_constraintdef(con.oid) !~ '''disputed''' LOOP EXECUTE format('ALTER TABLE public.orders DROP CONSTRAINT %I', c.conname); EXECUTE format('ALTER TABLE public.orders ADD CONSTRAINT %I CHECK (status = ANY (%L::text[])) NOT VALID', c.conname, ARRAY(SELECT DISTINCT m[1] FROM regexp_matches(c.def, '''([^'']+)''', 'g') AS m) || ARRAY['disputed']); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.creator_id = p_creator_id AND (p_product_id IS NULL OR o.product_id = p_product_id) ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status = 'pending', false)) AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;
REVOKE ALL ON FUNCTION public.orders_fill_creator() FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('32', '32_orders_keep_sales.sql', '27c3bdac03816affa13af31f3c345ab886a9cdea7ec6a45776264c38ef964706') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 33_site_customers.sql
/* Customer accounts on creators' websites, as a Shopify store has them: a visitor types their email on the website, gets a six digit code, types it back and is signed in, and a new email makes the account there and then. Three tables: the customers (one per website and email), the sign in codes (kept only as a keyed hash, ten minutes, five tries, used once) and each customer's saved products. An account belongs to one creator's website and is not a Storelib login: nothing here touches auth.users, profiles or creators. Server only: row level security on, closed to the public key. Until it runs, Sign in on a website says it is not available yet. Needs nothing else. Source: supabase/migrations/20261005_site_customers.sql. */
CREATE TABLE IF NOT EXISTS public.site_customers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, email text NOT NULL, name text, created_at timestamptz NOT NULL DEFAULT now(), last_sign_in_at timestamptz, CONSTRAINT site_customers_email_lower CHECK (email = lower(email)), CONSTRAINT site_customers_sizes CHECK (char_length(email) BETWEEN 3 AND 254 AND char_length(coalesce(name, '')) <= 120) );
CREATE UNIQUE INDEX IF NOT EXISTS site_customers_creator_email ON public.site_customers (creator_id, email);
ALTER TABLE public.site_customers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_customers FROM anon, authenticated;
GRANT ALL ON public.site_customers TO service_role;
CREATE TABLE IF NOT EXISTS public.site_customer_codes ( id uuid PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, email text NOT NULL, host text NOT NULL, code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT site_customer_codes_email_lower CHECK (email = lower(email)), CONSTRAINT site_customer_codes_attempts CHECK (attempts BETWEEN 0 AND 5) );
CREATE INDEX IF NOT EXISTS site_customer_codes_creator_email ON public.site_customer_codes (creator_id, email, created_at DESC);
CREATE INDEX IF NOT EXISTS site_customer_codes_created ON public.site_customer_codes (created_at);
ALTER TABLE public.site_customer_codes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_customer_codes FROM anon, authenticated;
GRANT ALL ON public.site_customer_codes TO service_role;
CREATE TABLE IF NOT EXISTS public.site_customer_wishlist ( customer_id uuid NOT NULL REFERENCES public.site_customers(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (customer_id, product_id) );
CREATE INDEX IF NOT EXISTS site_customer_wishlist_product ON public.site_customer_wishlist (product_id);
ALTER TABLE public.site_customer_wishlist ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_customer_wishlist FROM anon, authenticated;
GRANT ALL ON public.site_customer_wishlist TO service_role;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('33', '33_site_customers.sql', 'bb1a95605ab538442fb5bc0a7b2c456b68067931e06315af707a61165ab24206') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 34_theme_chat_attachments.sql
/* Ask Storelib pictures: the private bucket a conversation's pictures are kept in for thirty days, and one row per picture naming its message, readable only by the creator who owns the website and written by the server only. Until it runs, a sent picture shows while the chat is open and reads back as "Picture no longer available". Run after 24. Source: supabase/migrations/20261005_theme_chat_attachments.sql. */
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('theme-chat-attachments', 'theme-chat-attachments', false, 3145728, ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif']) ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 3145728, allowed_mime_types = ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif'];
CREATE TABLE IF NOT EXISTS public.theme_chat_attachments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), install_id uuid NOT NULL REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, message_id uuid REFERENCES public.theme_chat_messages(id) ON DELETE CASCADE, storage_path text NOT NULL, media_type text NOT NULL, byte_size integer NOT NULL DEFAULT 0, name text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '30 days') );
CREATE INDEX IF NOT EXISTS theme_chat_attachments_message_idx ON public.theme_chat_attachments (message_id);
CREATE INDEX IF NOT EXISTS theme_chat_attachments_expiry_idx ON public.theme_chat_attachments (expires_at);
CREATE INDEX IF NOT EXISTS theme_chat_attachments_install_idx ON public.theme_chat_attachments (install_id);
ALTER TABLE public.theme_chat_attachments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tca_own ON public.theme_chat_attachments;
DROP POLICY IF EXISTS tca_own_read ON public.theme_chat_attachments;
CREATE POLICY tca_own_read ON public.theme_chat_attachments FOR SELECT USING (install_id IN (SELECT i.id FROM public.store_theme_installs i JOIN public.creators c ON c.id = i.creator_id WHERE c.user_id = auth.uid()));
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('34', '34_theme_chat_attachments.sql', '40b6e5f5bd3eab573321a1f53a59016b648775fb68329b95a6f735d2638bae8f') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 35_product_variants_columns.sql
/* Product variants save and reorder: the compare at price and purchase limit columns the editor writes (scripts/055 was never in these parts), the old one variant per position rule taken off (it refused moving a variant up or down), the index the product page and checkout read variants by, and the one checkout counts sold options by. Needs product_variants and orders.variant_id; on a database without product_variants it changes nothing. Until it runs, saving a variant with a compare at price can fail with "column does not exist", and moving a variant can fail with a duplicate key error. */
ALTER TABLE IF EXISTS public.product_variants ADD COLUMN IF NOT EXISTS compare_at_price_cents integer;
ALTER TABLE IF EXISTS public.product_variants ADD COLUMN IF NOT EXISTS max_purchases integer;
ALTER TABLE IF EXISTS public.product_variants DROP CONSTRAINT IF EXISTS product_variants_product_position_unique;
DO $$ BEGIN IF to_regclass('public.product_variants') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_product_variants_position ON public.product_variants (product_id, position); END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'variant_id') THEN CREATE INDEX IF NOT EXISTS idx_orders_variant_status ON public.orders (variant_id, status) WHERE variant_id IS NOT NULL; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('35', '35_product_variants_columns.sql', '753499a75aae1503f3e0d4c63f85b373c08b9373b5e6cd79e5186f1b20db2207') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 36_order_business_details.sql
/* The company a buyer bought for, kept on the order: its legal name, tax number and address, as the checkout checked them (lib/checkout/business.ts). The buyer's invoice and the creator's copy of it read it. Adds one column, empty on every order already there; changes no rows. Written by the server only, as every order column is. Until it runs, orders are made as before and the company is read from the payment instead. */
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS business_details jsonb;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_business_details_shape') THEN ALTER TABLE public.orders ADD CONSTRAINT orders_business_details_shape CHECK (business_details IS NULL OR (jsonb_typeof(business_details) = 'object' AND pg_column_size(business_details) <= 4096)) NOT VALID; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('36', '36_order_business_details.sql', '07cdfcdf26b854110726e51bcd208e2acbb9d5bc0899215ad5ad70860ac63b16') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 37_own_ai_keys.sql
/* A creator's own AI: their Claude key, OpenAI key or OpenRouter account, which Storelib AI then answers on, outside the plan's AI edits. One new table, sealed keys only (lib/ai-keys/crypto.ts), row level security on with no policy so only the server reads it. Needs nothing else. Until it runs, Connections says connecting your own AI is not switched on yet and Storelib AI answers as before. */
CREATE TABLE IF NOT EXISTS public.creator_ai_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('anthropic', 'openai', 'openrouter')), sealed_key text NOT NULL CHECK (length(sealed_key) BETWEEN 20 AND 2000), key_hint text NOT NULL DEFAULT '' CHECK (length(key_hint) <= 8), created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, last_error text CHECK (last_error IS NULL OR length(last_error) <= 300), UNIQUE (creator_id, provider));
ALTER TABLE public.creator_ai_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.creator_ai_keys FROM anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('37', '37_own_ai_keys.sql', '95ddc5e5aa4c6576e9c2d505ef47166d83441b2ac054aa8cc942fa49e0dd9804') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 38_business_limit_three.sql
/* Business accounts: one login, up to three businesses. Part 26 allowed one business per login besides the first (a unique key on owner_id); this lets a login make two, and no more, and the database keeps the count itself so two presses at once cannot pass it. Adds an index for the owner's businesses and a trigger that counts them, then drops the old unique key. Changes no rows. Run after 26. Until it runs, a third business is refused and the account menu says it cannot be added just yet. Reasons: supabase/migrations/20261006_business_limit_three.sql. */
create index if not exists business_links_owner_created on public.business_links (owner_id, created_at);
create or replace function public.business_links_limit() returns trigger language plpgsql security definer set search_path = public as $$ begin perform pg_advisory_xact_lock(hashtextextended('business_links ' || new.owner_id::text, 0)); if 1 + (select count(*) from public.business_links where owner_id = new.owner_id and member_id <> new.member_id) >= 3 then raise exception 'One login can have at most 3 businesses' using errcode = 'check_violation', constraint = 'business_links_limit'; end if; return new; end; $$;
drop trigger if exists business_links_limit on public.business_links;
create trigger business_links_limit before insert or update of owner_id, member_id on public.business_links for each row execute function public.business_links_limit();
alter table public.business_links drop constraint if exists business_links_one_per_owner;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('38', '38_business_limit_three.sql', 'f70c992fa1f80be9a498c7d124ee9e82055d19e527b8e4fb9f117502cbb2ee5d') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 39_businesses_complete.sql
/* Businesses, complete: everything up to three businesses on one login relies on, in one part. Safe to run twice, and safe where parts 26 and 38 already ran (it leaves them as they are and fills in what is missing). The link between a login's first business and the ones it made (read only by the two accounts it links, written only by the server), a trigger that allows no chains, a trigger that counts a login to three with a lock so two presses at once cannot pass it, the index the app reads a login's businesses by, the server only log of switches, and the rate limit table the switch and create routes count in. Changes no rows. Needs nothing else. Reasons: supabase/migrations/20261007_businesses_complete.sql. */
/* The link: one row per business after the first, owner_id the login's first business, member_id the business it made. A business belongs to one login (member_id is the key), is never its own, and goes when either account is deleted. */
create table if not exists public.business_links (owner_id uuid not null references auth.users(id) on delete cascade, member_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), constraint business_links_pkey primary key (member_id), constraint business_links_not_self check (owner_id <> member_id));
alter table public.business_links drop constraint if exists business_links_not_self;
alter table public.business_links add constraint business_links_not_self check (owner_id <> member_id) not valid;
alter table public.business_links validate constraint business_links_not_self;
create index if not exists business_links_owner_created on public.business_links (owner_id, created_at);
/* Read only by the two accounts a row links; nothing a browser can write. The server writes with the service key. */
alter table public.business_links enable row level security;
drop policy if exists business_links_read on public.business_links;
create policy business_links_read on public.business_links for select using ((select auth.uid()) = owner_id or (select auth.uid()) = member_id);
revoke all on public.business_links from anon;
revoke insert, update, delete, truncate, references, trigger on public.business_links from authenticated;
grant select on public.business_links to authenticated;
grant all on public.business_links to service_role;
/* No chains: a business never owns one of its own, and a login's first business is never made a business of another. */
create or replace function public.business_links_no_chain() returns trigger language plpgsql security definer set search_path = public as $$ begin if exists (select 1 from public.business_links where member_id = new.owner_id) then raise exception 'A business account cannot own another business'; end if; if exists (select 1 from public.business_links where owner_id = new.member_id) then raise exception 'An account that owns a business cannot be added as one'; end if; return new; end; $$;
drop trigger if exists business_links_no_chain on public.business_links;
create trigger business_links_no_chain before insert or update on public.business_links for each row execute function public.business_links_no_chain();
/* Three businesses a login, its first included: the same number as MAX_BUSINESSES in lib/businesses/rules.ts. A lock per login makes two inserts at once take turns, so both cannot see room for one. Refused as check_violation (23514), which the app reads as the limit. */
create or replace function public.business_links_limit() returns trigger language plpgsql security definer set search_path = public as $$ begin perform pg_advisory_xact_lock(hashtextextended('business_links ' || new.owner_id::text, 0)); if 1 + (select count(*) from public.business_links where owner_id = new.owner_id and member_id <> new.member_id) >= 3 then raise exception 'One login can have at most 3 businesses' using errcode = 'check_violation', constraint = 'business_links_limit'; end if; return new; end; $$;
drop trigger if exists business_links_limit on public.business_links;
create trigger business_links_limit before insert or update of owner_id, member_id on public.business_links for each row execute function public.business_links_limit();
/* The old one business per login key from part 26 goes, now that the trigger above counts to three. */
alter table public.business_links drop constraint if exists business_links_one_per_owner;
/* The two trigger functions run as triggers only: nobody calls them through the API. */
revoke all on function public.business_links_no_chain() from public, anon, authenticated;
revoke all on function public.business_links_limit() from public, anon, authenticated;
/* Every switch, for support: who from, who to, when, from where. Server only; the app never reads it. */
create table if not exists public.business_switches (id bigint generated always as identity primary key, from_user uuid not null, to_user uuid not null, created_at timestamptz not null default now(), ip text, user_agent text);
alter table public.business_switches enable row level security;
revoke all on public.business_switches from anon, authenticated;
grant all on public.business_switches to service_role;
create index if not exists business_switches_from_created on public.business_switches (from_user, created_at desc);
/* The rate limit counter the switch (twenty a minute) and create (three an hour) routes count in, as part 01 makes it. Server only. */
create table if not exists public.rate_limit_hits (id bigserial primary key, bucket text not null, subject text not null, created_at timestamptz not null default now());
create index if not exists rate_limit_hits_lookup on public.rate_limit_hits (bucket, subject, created_at desc);
create index if not exists rate_limit_hits_sweep on public.rate_limit_hits (created_at);
alter table public.rate_limit_hits enable row level security;
revoke all on public.rate_limit_hits from anon, authenticated;
grant all on public.rate_limit_hits to service_role;
do $$ begin if to_regclass('public.rate_limit_hits_id_seq') is not null then grant usage, select on sequence public.rate_limit_hits_id_seq to service_role; end if; end $$;
/* The API sees the change at once. */
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('39', '39_businesses_complete.sql', 'c72c36051104d3095337847312116fb3d6ea9614d343ec0b424afa25279ec5be') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 40_notification_engine.sql
/* The notification engine (lib/notify): the outbox of domain events, the jobs planned from them (delayed ones by run_at), one delivery row per job and channel written before the send, people's notification preferences (readable by their owner), the email suppression list, the Mailgun webhook ids already handled, expires_at on the bell's rows, the two leased claims the worker takes work with, and the triggers that raise events from products, creators, custom_domains and auth.users in the same transaction as the change. Source: supabase/migrations/20261006_notification_engine.sql. Run after 29. Until it runs, emit() and the worker do nothing, the webhook handles Mailgun as before, and the bell reads as it did. */
/* 1. The outbox: one row per domain event, unique by its key, so the same event raised twice (a Stripe retry, a trigger and a route) is one row. Processed by the worker, retried with a lease until attempts run out. */
CREATE TABLE IF NOT EXISTS public.notification_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL, name text NOT NULL, user_id uuid, creator_id uuid, entity_type text, entity_id text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, source text NOT NULL DEFAULT 'app', correlation_id text, occurred_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, attempts integer NOT NULL DEFAULT 0, claimed_until timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT notification_events_key UNIQUE (event_key) );
CREATE INDEX IF NOT EXISTS notification_events_unprocessed ON public.notification_events (created_at) WHERE processed_at IS NULL;
CREATE INDEX IF NOT EXISTS notification_events_creator ON public.notification_events (creator_id, created_at DESC);
/* 2. The jobs: one per planned notification, unique by recipient, type, entity and step. A delayed job is a row with a later run_at; nothing waits in memory. */
CREATE TABLE IF NOT EXISTS public.notification_jobs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid REFERENCES public.notification_events(id) ON DELETE SET NULL, type text NOT NULL, recipient_type text NOT NULL, recipient_user_id uuid, recipient_email text, creator_id uuid, entity_type text, entity_id text, idempotency_key text NOT NULL, workflow text, step text, condition text, state text NOT NULL DEFAULT 'pending', skip_reason text, run_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, claimed_by text, claimed_until timestamptz, last_error text, data jsonb NOT NULL DEFAULT '{}'::jsonb, correlation_id text, sent_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT notification_jobs_once UNIQUE (idempotency_key) );
ALTER TABLE public.notification_jobs DROP CONSTRAINT IF EXISTS notification_jobs_state_check;
ALTER TABLE public.notification_jobs ADD CONSTRAINT notification_jobs_state_check CHECK (state IN ('pending', 'processing', 'sent', 'skipped', 'cancelled', 'failed')) NOT VALID;
ALTER TABLE public.notification_jobs DROP CONSTRAINT IF EXISTS notification_jobs_recipient_type_check;
ALTER TABLE public.notification_jobs ADD CONSTRAINT notification_jobs_recipient_type_check CHECK (recipient_type IN ('creator', 'customer', 'team_member', 'admin')) NOT VALID;
CREATE INDEX IF NOT EXISTS notification_jobs_due ON public.notification_jobs (state, run_at);
CREATE INDEX IF NOT EXISTS notification_jobs_leased ON public.notification_jobs (claimed_until) WHERE state = 'processing';
CREATE INDEX IF NOT EXISTS notification_jobs_expiring ON public.notification_jobs (expires_at) WHERE state = 'pending' AND expires_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS notification_jobs_workflow ON public.notification_jobs (workflow, recipient_user_id) WHERE state = 'pending';
CREATE INDEX IF NOT EXISTS notification_jobs_sent_to_user ON public.notification_jobs (type, recipient_user_id, entity_id, sent_at DESC) WHERE state = 'sent';
CREATE INDEX IF NOT EXISTS notification_jobs_sent_to_email ON public.notification_jobs (type, recipient_email, entity_id, sent_at DESC) WHERE state = 'sent';
CREATE INDEX IF NOT EXISTS notification_jobs_event ON public.notification_jobs (event_id);
CREATE INDEX IF NOT EXISTS notification_jobs_creator ON public.notification_jobs (creator_id, created_at DESC);
/* 3. The deliveries: one per job and channel, written in sending before the provider is called, so a worker that dies mid-send leaves a row that says so and the email is never sent again blindly. The Mailgun webhook moves it on by its id or its message id. */
CREATE TABLE IF NOT EXISTS public.notification_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.notification_jobs(id) ON DELETE CASCADE, channel text NOT NULL, provider text, provider_message_id text, status text NOT NULL DEFAULT 'sending', attempt_count integer NOT NULL DEFAULT 0, type text NOT NULL, category text, requirement text, recipient_email text, recipient_user_id uuid, correlation_id text, skip_reason text, failure_reason text, sent_at timestamptz, delivered_at timestamptz, failed_at timestamptz, opened_at timestamptz, clicked_at timestamptz, complained_at timestamptz, unsubscribed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT notification_deliveries_once UNIQUE (job_id, channel) );
ALTER TABLE public.notification_deliveries DROP CONSTRAINT IF EXISTS notification_deliveries_status_check;
ALTER TABLE public.notification_deliveries ADD CONSTRAINT notification_deliveries_status_check CHECK (status IN ('sending', 'sent', 'retry', 'failed', 'unknown', 'skipped', 'delivered', 'bounced', 'complained', 'unsubscribed')) NOT VALID;
ALTER TABLE public.notification_deliveries DROP CONSTRAINT IF EXISTS notification_deliveries_channel_check;
ALTER TABLE public.notification_deliveries ADD CONSTRAINT notification_deliveries_channel_check CHECK (channel IN ('email', 'in_app', 'push', 'sms')) NOT VALID;
CREATE INDEX IF NOT EXISTS notification_deliveries_provider_message ON public.notification_deliveries (provider_message_id) WHERE provider_message_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS notification_deliveries_recent_email ON public.notification_deliveries (recipient_email, created_at DESC) WHERE channel = 'email';
CREATE INDEX IF NOT EXISTS notification_deliveries_user ON public.notification_deliveries (recipient_user_id, created_at DESC);
/* 4. Preferences: one row per person, category and channel; no row means the default. The person reads their own rows; every write goes through the server. */
CREATE TABLE IF NOT EXISTS public.notification_preferences ( user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, category text NOT NULL, channel text NOT NULL, enabled boolean NOT NULL, source text NOT NULL DEFAULT 'settings', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, category, channel) );
ALTER TABLE public.notification_preferences DROP CONSTRAINT IF EXISTS notification_preferences_category_check;
ALTER TABLE public.notification_preferences ADD CONSTRAINT notification_preferences_category_check CHECK (category IN ('sales', 'payouts_and_payments', 'product_and_store', 'account', 'security', 'lifecycle', 'tips', 'marketing')) NOT VALID;
ALTER TABLE public.notification_preferences DROP CONSTRAINT IF EXISTS notification_preferences_channel_check;
ALTER TABLE public.notification_preferences ADD CONSTRAINT notification_preferences_channel_check CHECK (channel IN ('email', 'in_app', 'push', 'sms')) NOT VALID;
ALTER TABLE public.notification_preferences DROP CONSTRAINT IF EXISTS notification_preferences_source_check;
ALTER TABLE public.notification_preferences ADD CONSTRAINT notification_preferences_source_check CHECK (source IN ('settings', 'unsubscribe_link', 'mailgun', 'admin')) NOT VALID;
/* 5. Addresses not to email: all for a hard bounce, optional for a complaint or an unsubscribe. Stored lower case. The webhook ids already handled, so a retried delivery changes nothing twice. */
CREATE TABLE IF NOT EXISTS public.email_suppressions ( email text NOT NULL, scope text NOT NULL, reason text, source text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), lifted_at timestamptz, PRIMARY KEY (email, scope) );
ALTER TABLE public.email_suppressions DROP CONSTRAINT IF EXISTS email_suppressions_scope_check;
ALTER TABLE public.email_suppressions ADD CONSTRAINT email_suppressions_scope_check CHECK (scope IN ('all', 'optional') AND email = lower(email)) NOT VALID;
CREATE TABLE IF NOT EXISTS public.mailgun_webhook_events ( id text PRIMARY KEY, event text, received_at timestamptz NOT NULL DEFAULT now() );
CREATE INDEX IF NOT EXISTS mailgun_webhook_events_received ON public.mailgun_webhook_events (received_at);
/* 6. The bell: the engine writes its rows into seller_notifications with a type the check already allows and its notification type as the kind, so only an expiry is added. */
ALTER TABLE IF EXISTS public.seller_notifications ADD COLUMN IF NOT EXISTS expires_at timestamptz;
DO $$ BEGIN IF to_regclass('public.seller_notifications') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS seller_notifications_expiring ON public.seller_notifications (expires_at) WHERE expires_at IS NOT NULL; END IF; END $$;
/* 7. Server only, except that a person may read their own preferences. */
ALTER TABLE public.notification_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.email_suppressions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mailgun_webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.notification_events FROM anon, authenticated;
REVOKE ALL ON public.notification_jobs FROM anon, authenticated;
REVOKE ALL ON public.notification_deliveries FROM anon, authenticated;
REVOKE ALL ON public.email_suppressions FROM anon, authenticated;
REVOKE ALL ON public.mailgun_webhook_events FROM anon, authenticated;
REVOKE ALL ON public.notification_preferences FROM anon;
REVOKE INSERT, UPDATE, DELETE ON public.notification_preferences FROM authenticated;
GRANT SELECT ON public.notification_preferences TO authenticated;
DROP POLICY IF EXISTS "People read their own notification preferences" ON public.notification_preferences;
CREATE POLICY "People read their own notification preferences" ON public.notification_preferences FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
GRANT ALL ON public.notification_events TO service_role;
GRANT ALL ON public.notification_jobs TO service_role;
GRANT ALL ON public.notification_deliveries TO service_role;
GRANT ALL ON public.email_suppressions TO service_role;
GRANT ALL ON public.mailgun_webhook_events TO service_role;
GRANT ALL ON public.notification_preferences TO service_role;
/* 8. The claims. Events: unprocessed ones no other run holds, oldest first, leased. Jobs: pending ones past expiry are skipped as EXPIRED first, then due pending ones and ones whose lease ran out (a worker that died) are leased to this worker with FOR UPDATE SKIP LOCKED and their attempt counted. Run by the server only. */
CREATE OR REPLACE FUNCTION public.claim_notification_events(p_limit integer DEFAULT 20, p_lease_seconds integer DEFAULT 60) RETURNS SETOF public.notification_events LANGUAGE sql SECURITY DEFINER SET search_path = public AS $fn$ UPDATE public.notification_events e SET claimed_until = now() + make_interval(secs => greatest(15, least(coalesce(p_lease_seconds, 60), 900))), attempts = e.attempts + 1 WHERE e.id IN (SELECT q.id FROM public.notification_events q WHERE q.processed_at IS NULL AND (q.claimed_until IS NULL OR q.claimed_until < now()) AND q.attempts < 10 ORDER BY q.created_at LIMIT greatest(1, least(coalesce(p_limit, 20), 100)) FOR UPDATE SKIP LOCKED) RETURNING e.*; $fn$;
REVOKE ALL ON FUNCTION public.claim_notification_events(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_notification_events(integer, integer) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_notification_jobs(p_worker text, p_limit integer DEFAULT 20, p_lease_seconds integer DEFAULT 120) RETURNS SETOF public.notification_jobs LANGUAGE sql SECURITY DEFINER SET search_path = public AS $fn$ UPDATE public.notification_jobs x SET state = 'skipped', skip_reason = 'EXPIRED', claimed_by = NULL, claimed_until = NULL, finished_at = now(), updated_at = now() WHERE x.state = 'pending' AND x.expires_at IS NOT NULL AND x.expires_at <= now(); UPDATE public.notification_jobs j SET state = 'processing', claimed_by = p_worker, claimed_until = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 120), 900))), attempts = j.attempts + 1, updated_at = now() WHERE j.id IN (SELECT q.id FROM public.notification_jobs q WHERE ((q.state = 'pending' AND q.run_at <= now()) OR (q.state = 'processing' AND q.claimed_until < now())) AND (q.expires_at IS NULL OR q.expires_at > now()) ORDER BY q.run_at LIMIT greatest(1, least(coalesce(p_limit, 20), 100)) FOR UPDATE SKIP LOCKED) RETURNING j.*; $fn$;
REVOKE ALL ON FUNCTION public.claim_notification_jobs(text, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_notification_jobs(text, integer, integer) TO service_role;
/* 9. The outbox from inside the database: a row in notification_events, keyed so a duplicate fire is one row, and never an error. A failure is a warning in the log and the business write goes on. The stamp in a key is the row's updated_at when this change moved it, else the transaction's time, so a real second publish later is a new event and a repeated fire is not. */
CREATE OR REPLACE FUNCTION public.notify_outbox_insert(p_name text, p_key text, p_user uuid, p_creator uuid, p_entity_type text, p_entity_id text, p_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN INSERT INTO public.notification_events (event_key, name, user_id, creator_id, entity_type, entity_id, payload, source, correlation_id) VALUES (left(p_key, 500), p_name, p_user, p_creator, p_entity_type, p_entity_id, coalesce(p_payload, '{}'::jsonb), 'trigger', gen_random_uuid()::text) ON CONFLICT (event_key) DO NOTHING; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'notification event % not recorded (%)', p_name, SQLSTATE; END $fn$;
REVOKE ALL ON FUNCTION public.notify_outbox_insert(text, text, uuid, uuid, text, text, jsonb) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.notify_stamp(o jsonb, n jsonb) RETURNS text LANGUAGE sql STABLE SET search_path = public AS $fn$ SELECT CASE WHEN n ->> 'updated_at' IS NOT NULL AND (o IS NULL OR (o ->> 'updated_at') IS DISTINCT FROM (n ->> 'updated_at')) THEN floor(extract(epoch FROM (n ->> 'updated_at')::timestamptz) * 1000000)::bigint::text ELSE floor(extract(epoch FROM now()) * 1000000)::bigint::text END $fn$;
REVOKE ALL ON FUNCTION public.notify_stamp(jsonb, jsonb) FROM PUBLIC, anon, authenticated;
/* 10. Products are written from the browser, so their events come from here: product.created on insert; product.published when the status moves into published, and product.first_published (once per creator, ever) when no other product of theirs is published; product.deleted on delete or when it is archived. Columns are read through to_jsonb, so a column a database lacks is a null, not an error. */
CREATE OR REPLACE FUNCTION public.notify_products_outbox() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE n jsonb; o jsonb; v_id text; v_creator uuid; v_user uuid; v_stamp text; v_payload jsonb; v_ready boolean; BEGIN BEGIN IF TG_OP <> 'DELETE' THEN n := to_jsonb(NEW); END IF; IF TG_OP <> 'INSERT' THEN o := to_jsonb(OLD); END IF; v_id := coalesce(n ->> 'id', o ->> 'id'); v_creator := nullif(coalesce(n ->> 'creator_id', o ->> 'creator_id'), '')::uuid; SELECT c.user_id INTO v_user FROM public.creators c WHERE c.id = v_creator; v_stamp := public.notify_stamp(o, n); v_payload := jsonb_build_object('productId', v_id, 'productTitle', left(coalesce(n ->> 'title', o ->> 'title', ''), 200), 'status', coalesce(n ->> 'status', o ->> 'status')); IF TG_OP = 'INSERT' THEN PERFORM public.notify_outbox_insert('product.created', 'product.created:' || v_id, v_user, v_creator, 'product', v_id, v_payload); END IF; IF TG_OP <> 'DELETE' AND n ->> 'status' = 'published' AND (o IS NULL OR (o ->> 'status') IS DISTINCT FROM 'published') THEN PERFORM public.notify_outbox_insert('product.published', 'product.published:' || v_id || ':' || v_stamp, v_user, v_creator, 'product', v_id, v_payload); IF NOT EXISTS (SELECT 1 FROM public.products p WHERE p.creator_id = v_creator AND p.id::text <> v_id AND p.status = 'published') THEN SELECT coalesce(to_jsonb(c) ->> 'charges_enabled', 'false') = 'true' INTO v_ready FROM public.creators c WHERE c.id = v_creator; PERFORM public.notify_outbox_insert('product.first_published', 'product.first_published:' || v_creator::text, v_user, v_creator, 'product', v_id, v_payload || jsonb_build_object('paymentsReady', coalesce(v_ready, false))); END IF; END IF; IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND ((n ->> 'status' = 'archived' AND (o ->> 'status') IS DISTINCT FROM 'archived') OR (coalesce(n ->> 'archived', 'false') = 'true' AND coalesce(o ->> 'archived', 'false') <> 'true'))) THEN PERFORM public.notify_outbox_insert('product.deleted', 'product.deleted:' || v_id || ':' || v_stamp, v_user, v_creator, 'product', v_id, v_payload); END IF; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'notification trigger on products skipped (%)', SQLSTATE; END; RETURN NULL; END $fn$;
REVOKE ALL ON FUNCTION public.notify_products_outbox() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('public.products') IS NOT NULL THEN DROP TRIGGER IF EXISTS notify_products_outbox ON public.products; CREATE TRIGGER notify_products_outbox AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.notify_products_outbox(); END IF; END $$;
/* 11. Creators: store.created on insert; the Stripe Connect fields moving to connected (payment_setup.completed), away from it (payment_setup.action_required), a Stripe account first saved (payment_setup.started), a rejected or restricted status (payment_setup.failed); banned_at set or cleared (account.restricted, account.restriction_removed). */
CREATE OR REPLACE FUNCTION public.notify_creators_outbox() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE n jsonb; o jsonb; v_id text; v_user uuid; v_stamp text; v_new boolean; v_old boolean; v_base jsonb; BEGIN BEGIN n := to_jsonb(NEW); IF TG_OP = 'UPDATE' THEN o := to_jsonb(OLD); END IF; v_id := n ->> 'id'; v_user := nullif(n ->> 'user_id', '')::uuid; v_stamp := public.notify_stamp(o, n); v_base := jsonb_build_object('creatorId', v_id, 'storeName', left(coalesce(n ->> 'display_name', n ->> 'username', ''), 120)); IF TG_OP = 'INSERT' THEN PERFORM public.notify_outbox_insert('store.created', 'store.created:' || v_id, v_user, v_id::uuid, 'creator', v_id, v_base); RETURN NULL; END IF; v_new := coalesce(n ->> 'stripe_onboarding_status', '') = 'connected' OR (coalesce(n ->> 'charges_enabled', '') = 'true' AND coalesce(n ->> 'payouts_enabled', '') = 'true' AND coalesce(n ->> 'details_submitted', '') = 'true'); v_old := coalesce(o ->> 'stripe_onboarding_status', '') = 'connected' OR (coalesce(o ->> 'charges_enabled', '') = 'true' AND coalesce(o ->> 'payouts_enabled', '') = 'true' AND coalesce(o ->> 'details_submitted', '') = 'true'); IF (o ->> 'stripe_account_id') IS NULL AND (n ->> 'stripe_account_id') IS NOT NULL THEN PERFORM public.notify_outbox_insert('payment_setup.started', 'payment_setup.started:' || v_id || ':' || v_stamp, v_user, v_id::uuid, 'payment_setup', v_id, v_base); END IF; IF v_new AND NOT v_old THEN PERFORM public.notify_outbox_insert('payment_setup.completed', 'payment_setup.completed:' || v_id || ':' || v_stamp, v_user, v_id::uuid, 'payment_setup', v_id, v_base); ELSIF v_old AND NOT v_new AND (n ->> 'stripe_account_id') IS NOT NULL THEN PERFORM public.notify_outbox_insert('payment_setup.action_required', 'payment_setup.action_required:' || v_id || ':' || v_stamp, v_user, v_id::uuid, 'payment_setup', v_id, v_base || jsonb_build_object('chargesEnabled', coalesce(n ->> 'charges_enabled', '') = 'true', 'payoutsEnabled', coalesce(n ->> 'payouts_enabled', '') = 'true')); END IF; IF coalesce(n ->> 'stripe_onboarding_status', '') IN ('rejected', 'failed', 'restricted') AND (o ->> 'stripe_onboarding_status') IS DISTINCT FROM (n ->> 'stripe_onboarding_status') THEN PERFORM public.notify_outbox_insert('payment_setup.failed', 'payment_setup.failed:' || v_id || ':' || v_stamp, v_user, v_id::uuid, 'payment_setup', v_id, v_base || jsonb_build_object('reason', n ->> 'stripe_onboarding_status')); END IF; IF (o ->> 'banned_at') IS NULL AND (n ->> 'banned_at') IS NOT NULL THEN PERFORM public.notify_outbox_insert('account.restricted', 'account.restricted:' || v_id || ':' || v_stamp, v_user, v_id::uuid, 'creator', v_id, v_base); ELSIF (o ->> 'banned_at') IS NOT NULL AND (n ->> 'banned_at') IS NULL THEN PERFORM public.notify_outbox_insert('account.restriction_removed', 'account.restriction_removed:' || v_id || ':' || v_stamp, v_user, v_id::uuid, 'creator', v_id, v_base); END IF; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'notification trigger on creators skipped (%)', SQLSTATE; END; RETURN NULL; END $fn$;
REVOKE ALL ON FUNCTION public.notify_creators_outbox() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('public.creators') IS NOT NULL THEN DROP TRIGGER IF EXISTS notify_creators_outbox ON public.creators; CREATE TRIGGER notify_creators_outbox AFTER INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.notify_creators_outbox(); END IF; END $$;
/* 12. Connected domains: the status moving to active (domain.connected), or the status or the certificate moving to failed (domain.connection_failed). */
CREATE OR REPLACE FUNCTION public.notify_domains_outbox() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE n jsonb; o jsonb; v_id text; v_creator uuid; v_user uuid; v_stamp text; v_payload jsonb; BEGIN BEGIN n := to_jsonb(NEW); IF TG_OP = 'UPDATE' THEN o := to_jsonb(OLD); END IF; v_id := n ->> 'id'; v_creator := nullif(n ->> 'creator_id', '')::uuid; SELECT c.user_id INTO v_user FROM public.creators c WHERE c.id = v_creator; v_stamp := public.notify_stamp(o, n); v_payload := jsonb_build_object('domainId', v_id, 'domain', left(coalesce(n ->> 'domain', ''), 253)); IF n ->> 'status' = 'active' AND (o IS NULL OR (o ->> 'status') IS DISTINCT FROM 'active') THEN PERFORM public.notify_outbox_insert('domain.connected', 'domain.connected:' || v_id || ':' || v_stamp, v_user, v_creator, 'domain', v_id, v_payload); END IF; IF (n ->> 'status' = 'failed' AND (o IS NULL OR (o ->> 'status') IS DISTINCT FROM 'failed')) OR (n ->> 'ssl_status' = 'failed' AND (o IS NULL OR (o ->> 'ssl_status') IS DISTINCT FROM 'failed')) THEN PERFORM public.notify_outbox_insert('domain.connection_failed', 'domain.connection_failed:' || v_id || ':' || v_stamp, v_user, v_creator, 'domain', v_id, v_payload); END IF; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'notification trigger on custom_domains skipped (%)', SQLSTATE; END; RETURN NULL; END $fn$;
REVOKE ALL ON FUNCTION public.notify_domains_outbox() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('public.custom_domains') IS NOT NULL THEN DROP TRIGGER IF EXISTS notify_domains_outbox ON public.custom_domains; CREATE TRIGGER notify_domains_outbox AFTER INSERT OR UPDATE ON public.custom_domains FOR EACH ROW EXECUTE FUNCTION public.notify_domains_outbox(); END IF; END $$;
/* 13. Supabase Auth: a password that changed (user.password_changed, keyed by the user and updated_at in seconds, as the app route keys it, so the two are one event) and an email that changed (user.email_changed, with the old and the new address). Created only when this role may add a trigger to auth.users; otherwise a notice, and those events come from the app routes alone. */
CREATE OR REPLACE FUNCTION public.notify_auth_users_outbox() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_creator uuid; v_epoch text; BEGIN BEGIN v_epoch := floor(extract(epoch FROM coalesce(NEW.updated_at, now())))::bigint::text; SELECT c.id INTO v_creator FROM public.creators c WHERE c.user_id = NEW.id LIMIT 1; IF NEW.encrypted_password IS DISTINCT FROM OLD.encrypted_password AND coalesce(OLD.encrypted_password, '') <> '' THEN PERFORM public.notify_outbox_insert('user.password_changed', 'user.password_changed:' || NEW.id::text || ':' || v_epoch, NEW.id, v_creator, 'user', NEW.id::text, jsonb_build_object('userId', NEW.id)); END IF; IF NEW.email IS DISTINCT FROM OLD.email AND OLD.email IS NOT NULL THEN PERFORM public.notify_outbox_insert('user.email_changed', 'user.email_changed:' || NEW.id::text || ':' || v_epoch, NEW.id, v_creator, 'user', NEW.id::text, jsonb_build_object('userId', NEW.id, 'previousEmail', OLD.email, 'newEmail', NEW.email)); END IF; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'notification trigger on auth.users skipped (%)', SQLSTATE; END; RETURN NULL; END $fn$;
REVOKE ALL ON FUNCTION public.notify_auth_users_outbox() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('auth.users') IS NULL THEN RAISE NOTICE 'auth.users not found: password and email change events come from the app routes only'; ELSIF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'notify_auth_users_outbox' AND tgrelid = 'auth.users'::regclass AND NOT tgisinternal) THEN RAISE NOTICE 'auth.users trigger already in place'; ELSIF NOT has_table_privilege('auth.users', 'TRIGGER') THEN RAISE NOTICE 'auth.users trigger skipped: this role may not add triggers there, so password and email change events come from the app routes only'; ELSE CREATE TRIGGER notify_auth_users_outbox AFTER UPDATE OF encrypted_password, email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.notify_auth_users_outbox(); END IF; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'auth.users trigger skipped: not permitted for this role, so password and email change events come from the app routes only'; END $$;
/* PostgREST answers from its cached schema; without this the API keeps saying the new tables and functions do not exist. */
NOTIFY pgrst, 'reload schema';
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('40', '40_notification_engine.sql', '5edb1633aa4e13eb186b39142f063f4d571bb77ef2e40477cd9bd6204d5fa21d') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 41_notification_admin.sql
/* Notification admin: one read only function, server only, that counts the notification engine's jobs and deliveries by type and status over the last days (queued, sent, delivered, failed, bounced, opened, clicked, unsubscribed, complained), why jobs were skipped, and for each onboarding reminder how many of the people it reached did the task within three days (a product created, published, or payment setup finished). /admin/notifications reads it through /api/admin/notifications. Run after 40. Changes no data. */
CREATE OR REPLACE FUNCTION public.notification_admin_stats(p_days integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $fn$ DECLARE since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 7), 1), 90)); result jsonb; BEGIN SELECT jsonb_build_object('since', since, 'jobs', coalesce((SELECT jsonb_agg(t ORDER BY t.total DESC) FROM (SELECT j.type, count(*) AS total, count(*) FILTER (WHERE j.state IN ('pending', 'processing')) AS queued, count(*) FILTER (WHERE j.state = 'sent') AS sent, count(*) FILTER (WHERE j.state = 'skipped') AS skipped, count(*) FILTER (WHERE j.state = 'cancelled') AS cancelled, count(*) FILTER (WHERE j.state = 'failed' AND NOT EXISTS (SELECT 1 FROM public.notification_deliveries fd WHERE fd.job_id = j.id AND (fd.status IN ('failed', 'bounced') OR fd.failed_at IS NOT NULL))) AS failed FROM public.notification_jobs j WHERE j.created_at >= since GROUP BY j.type) t), '[]'::jsonb), 'deliveries', coalesce((SELECT jsonb_agg(d ORDER BY d.type, d.channel) FROM (SELECT x.type, x.channel, count(*) AS total, count(*) FILTER (WHERE x.sent_at IS NOT NULL OR x.status IN ('sent', 'delivered')) AS sent, count(*) FILTER (WHERE x.delivered_at IS NOT NULL OR x.status = 'delivered') AS delivered, count(*) FILTER (WHERE x.status = 'failed' OR (x.failed_at IS NOT NULL AND x.status <> 'bounced')) AS failed, count(*) FILTER (WHERE x.status = 'bounced') AS bounced, count(*) FILTER (WHERE x.opened_at IS NOT NULL) AS opened, count(*) FILTER (WHERE x.clicked_at IS NOT NULL) AS clicked, count(*) FILTER (WHERE x.unsubscribed_at IS NOT NULL OR x.status = 'unsubscribed') AS unsubscribed, count(*) FILTER (WHERE x.complained_at IS NOT NULL OR x.status = 'complained') AS complained, count(*) FILTER (WHERE x.status = 'skipped') AS skipped FROM public.notification_deliveries x WHERE x.created_at >= since GROUP BY x.type, x.channel) d), '[]'::jsonb), 'skip_reasons', coalesce((SELECT jsonb_agg(s ORDER BY s.n DESC) FROM (SELECT j.skip_reason AS reason, count(*) AS n FROM public.notification_jobs j WHERE j.created_at >= since AND j.state = 'skipped' GROUP BY j.skip_reason) s), '[]'::jsonb), 'lifecycle', coalesce((SELECT jsonb_agg(l ORDER BY l.type) FROM (SELECT j.type, count(DISTINCT j.recipient_user_id) AS reminded, count(DISTINCT j.recipient_user_id) FILTER (WHERE j.sent_at <= now() - interval '3 days') AS settled, count(DISTINCT j.recipient_user_id) FILTER (WHERE j.sent_at <= now() - interval '3 days' AND (EXISTS (SELECT 1 FROM public.notification_events e WHERE e.user_id = j.recipient_user_id AND e.occurred_at > j.sent_at AND e.occurred_at <= j.sent_at + interval '3 days' AND e.name::text = ANY (CASE WHEN j.type IN ('FIRST_PRODUCT_REMINDER', 'FIRST_PRODUCT_REMINDER_2') THEN ARRAY['product.created'] WHEN j.type IN ('FINISH_PRODUCT_REMINDER', 'PUBLISH_PRODUCT_REMINDER') THEN ARRAY['product.published', 'product.first_published'] ELSE ARRAY['payment_setup.completed'] END)) OR (j.type IN ('FIRST_PRODUCT_REMINDER', 'FIRST_PRODUCT_REMINDER_2') AND EXISTS (SELECT 1 FROM public.products p JOIN public.creators c ON c.id = p.creator_id WHERE c.user_id = j.recipient_user_id AND p.created_at > j.sent_at AND p.created_at <= j.sent_at + interval '3 days')))) AS completed FROM public.notification_jobs j WHERE j.state = 'sent' AND j.sent_at >= since AND j.recipient_user_id IS NOT NULL AND j.type IN ('FIRST_PRODUCT_REMINDER', 'FIRST_PRODUCT_REMINDER_2', 'FINISH_PRODUCT_REMINDER', 'PUBLISH_PRODUCT_REMINDER', 'PAYMENT_SETUP_REMINDER', 'PAYMENT_SETUP_REMINDER_2') GROUP BY j.type) l), '[]'::jsonb)) INTO result; RETURN result; END; $fn$;
REVOKE ALL ON FUNCTION public.notification_admin_stats(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.notification_admin_stats(integer) TO service_role;
NOTIFY pgrst, 'reload schema';
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('41', '41_notification_admin.sql', '0be4d68c08ddbb7ca42e9316f71b0afa2b42c9dc64fa343a1963d08d1305170a') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 42_email_logs_rls.sql
/* Receipt email records made server only: row level security on, nothing for visitors or signed in users, everything for the service role. They were readable and writable by any signed in user (GRANT ALL TO authenticated, no row level security), and every reader and writer is server code with the service role (lib/email.tsx, receipt resend, the admin console). Changes no rows. Changes nothing where the table does not exist. Source: supabase/migrations/20261007_email_logs_rls.sql. */
DO $$ BEGIN IF to_regclass('public.email_logs') IS NOT NULL THEN ALTER TABLE public.email_logs ENABLE ROW LEVEL SECURITY; REVOKE ALL ON TABLE public.email_logs FROM anon, authenticated; GRANT ALL ON TABLE public.email_logs TO service_role; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('42', '42_email_logs_rls.sql', '6081ea0fdd589c8d72fc6e12f20b11c71f8faf45747e53c8ce0415bb8c5dc927') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 43_onepage_forget_deleted_product.sql
/* A deleted product leaves the OnePage that named it. A OnePage product block keeps a copy of the product inside onepages.draft_blocks and published_blocks (its title, price, picture and address), so deleting the product left the row on the page with its picture and a button to a page that is now a 404. The live page reads the product row instead of the copy now (lib/onepage/live-products.ts), so a visitor is right with or without this part; this is what takes the block out of the creator's own editor, and out of the stored page, for good. One function that removes every mention of one product from a block array (groups included, and an email capture block keeps collecting addresses but stops offering the deleted file), a trigger that calls it when a product is deleted, and a one off pass over the pages that already hold a block for a product that is gone. Deletes no product, no order and no page: only blocks naming a product that no longer exists. Changes nothing where onepages is missing. Safe to run again: the second run finds nothing to change. */
CREATE OR REPLACE FUNCTION public.onepage_blocks_without_product(p_blocks jsonb, p_product_id text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $fn$ DECLARE v_out jsonb := '[]'::jsonb; v_block jsonb; v_data jsonb; BEGIN IF p_blocks IS NULL OR jsonb_typeof(p_blocks) <> 'array' OR coalesce(p_product_id, '') = '' THEN RETURN p_blocks; END IF; FOR v_block IN SELECT value FROM jsonb_array_elements(p_blocks) LOOP v_data := CASE WHEN jsonb_typeof(v_block -> 'data') = 'object' THEN v_block -> 'data' ELSE '{}'::jsonb END; IF v_block ->> 'type' = 'product' AND v_data ->> 'product_id' = p_product_id THEN CONTINUE; END IF; IF v_block ->> 'type' = 'email_capture' AND v_data ->> 'digital_product_id' = p_product_id THEN v_block := jsonb_set(v_block, '{data}', v_data || jsonb_build_object('enable_digital_product', false, 'digital_product_id', null::text, 'digital_product_title', null::text, 'digital_product_thumbnail', null::text, 'digital_product_file_url', null::text)); ELSIF v_block ->> 'type' = 'group' AND jsonb_typeof(v_data -> 'children') = 'array' THEN v_block := jsonb_set(v_block, '{data}', jsonb_set(v_data, '{children}', public.onepage_blocks_without_product(v_data -> 'children', p_product_id))); END IF; v_out := v_out || jsonb_build_array(v_block); END LOOP; RETURN v_out; END $fn$;
CREATE OR REPLACE FUNCTION public.onepages_forget_deleted_product() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_owner uuid; BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN OLD; END IF; SELECT c.user_id INTO v_owner FROM public.creators c WHERE c.id = OLD.creator_id; UPDATE public.onepages o SET draft_blocks = public.onepage_blocks_without_product(o.draft_blocks, OLD.id::text), published_blocks = public.onepage_blocks_without_product(o.published_blocks, OLD.id::text) WHERE (o.seller_id = OLD.creator_id OR o.creator_id = OLD.creator_id OR (v_owner IS NOT NULL AND o.owner_id = v_owner)) AND (coalesce(o.draft_blocks::text, '') LIKE '%' || OLD.id::text || '%' OR coalesce(o.published_blocks::text, '') LIKE '%' || OLD.id::text || '%'); RETURN OLD; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'onepages_forget_deleted_product skipped for %: %', OLD.id, SQLERRM; RETURN OLD; END $fn$;
DROP TRIGGER IF EXISTS onepages_forget_deleted_product ON public.products;
CREATE TRIGGER onepages_forget_deleted_product AFTER DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.onepages_forget_deleted_product();
DO $$ DECLARE r record; v_id text; BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN; END IF; FOR r IN SELECT o.id AS page_id, coalesce(o.draft_blocks::text, '') || coalesce(o.published_blocks::text, '') AS blob FROM public.onepages o LOOP FOR v_id IN SELECT DISTINCT m[1] FROM regexp_matches(r.blob, '"(?:product_id|digital_product_id)"[[:space:]]*:[[:space:]]*"([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})"', 'g') AS m LOOP IF NOT EXISTS (SELECT 1 FROM public.products p WHERE p.id = v_id::uuid) THEN UPDATE public.onepages o SET draft_blocks = public.onepage_blocks_without_product(o.draft_blocks, v_id), published_blocks = public.onepage_blocks_without_product(o.published_blocks, v_id) WHERE o.id = r.page_id; END IF; END LOOP; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.onepages_forget_deleted_product() FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('43', '43_onepage_forget_deleted_product.sql', '8648a6c5576fa6b610523b094fb30153e194939c0853baec862567063f961eab') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 44_profile_identity_follows.sql
/* The name and the photo have one home, and every copy of them follows it. profiles.display_name and profiles.avatar_url are the creator's name and face; the OnePage keeps a copy in its title, in the copy taken when it was published, and in the SEO card's Meta title, the creators row keeps two columns of its own, and the creator page keeps the store name and the header photo. None of them moved when the profile changed, so a creator who renamed themselves kept the old name in their page's tab title and the old picture as its icon until they republished. This adds a trigger that moves every copy that STILL HOLDS THE OLD VALUE (a title somebody typed is left alone) and never lets that work fail a profile save, plus a one off pass for the copies already stale. Run after nothing; needs only the profiles, onepages, creators and store_builder_configs tables. Until it runs, the app does the same work from its own routes (lib/account/profile-follow), which covers Settings, the storefront's Edit profile and the photo save. */
CREATE OR REPLACE FUNCTION public.storelib_provider_photo(url text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(btrim(url) ~* '^https?://(([a-z0-9-]+\.)*googleusercontent\.com/(a|a-)/|([a-z0-9-]+\.)*googleusercontent\.com/-[^/]+/AAAAAAAAAAI/|graph\.facebook\.com/(v[0-9.]+/)?[^/]+/picture([/?]|$)|platform-lookaside\.fbsbx\.com/platform/profilepic/|pbs\.twimg\.com/profile_images/|avatars\.githubusercontent\.com/|cdn\.discordapp\.com/avatars/|media(-exp[0-9])?\.licdn\.com/dms/image/[^?]*profile-displayphoto)', false) $$;
/* A copy follows only when it is still what the profile held: empty stays empty (it already falls back to the profile), anything else was chosen by somebody and stays. */
CREATE OR REPLACE FUNCTION public.storelib_follow_text(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN nullif(btrim(coalesce(stored, '')), '') IS NULL THEN stored WHEN nullif(btrim(coalesce(was, '')), '') IS NOT NULL AND lower(btrim(stored)) = lower(btrim(was)) THEN now_value ELSE stored END $$;
/* The same for a photo, with two differences: it follows only when it is exactly the address the profile held (two addresses that differ in case are two files), and the account picture a sign in provider sent (Google's /a/ address, not every picture on Google's servers) is never one somebody chose, so it follows whatever the profile now says, a removal included. A photo uploaded to the OnePage is its own file and is never touched. */
CREATE OR REPLACE FUNCTION public.storelib_follow_photo(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN nullif(btrim(coalesce(stored, '')), '') IS NULL THEN stored WHEN public.storelib_provider_photo(stored) THEN now_value WHEN nullif(btrim(coalesce(was, '')), '') IS NOT NULL AND btrim(stored) = btrim(was) THEN now_value ELSE stored END $$;
/* The creator page config: the store name it shows, and the header photo, which keeps '' to mean "show my initials". */
CREATE OR REPLACE FUNCTION public.storelib_follow_config(cfg jsonb, nb text, na text, pb text, pa text, nm boolean, pm boolean) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN jsonb_typeof(cfg) <> 'object' THEN cfg ELSE (SELECT CASE WHEN nm AND jsonb_typeof(c1->'globalSettings') = 'object' AND c1#>>'{globalSettings,storeName}' IS NOT NULL THEN jsonb_set(c1, '{globalSettings,storeName}', to_jsonb(coalesce(public.storelib_follow_text(c1#>>'{globalSettings,storeName}', nb, na), ''))) ELSE c1 END FROM (SELECT CASE WHEN pm AND jsonb_typeof(cfg->'headerSettings') = 'object' AND cfg#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(cfg, '{headerSettings,avatarUrl}', to_jsonb(coalesce(public.storelib_follow_photo(cfg#>>'{headerSettings,avatarUrl}', pb, pa), ''))) ELSE cfg END AS c1) s) END $$;
/* The trigger itself. Everything it writes is inside a block that swallows its own errors: a copy that did not move is a copy the next save moves, and a rename must never fail because of one. */
CREATE OR REPLACE FUNCTION public.profiles_identity_follows() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE nb text := nullif(btrim(coalesce(old.display_name, '')), ''); na text := nullif(btrim(coalesce(new.display_name, '')), ''); pb text := nullif(btrim(coalesce(old.avatar_url, '')), ''); pa text := nullif(btrim(coalesce(new.avatar_url, '')), ''); nm boolean; pm boolean; cid uuid; BEGIN nm := nb IS DISTINCT FROM na; pm := pb IS DISTINCT FROM pa; IF NOT nm AND NOT pm THEN RETURN new; END IF; BEGIN UPDATE public.onepages o SET title = CASE WHEN nm THEN public.storelib_follow_text(o.title, nb, na) ELSE o.title END, avatar_url = CASE WHEN pm THEN public.storelib_follow_photo(o.avatar_url, pb, pa) ELSE o.avatar_url END, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(jsonb_set(o.published_profile, '{title}', coalesce(to_jsonb(CASE WHEN nm THEN public.storelib_follow_text(o.published_profile->>'title', nb, na) ELSE o.published_profile->>'title' END), 'null'::jsonb)), '{avatar_url}', coalesce(to_jsonb(CASE WHEN pm THEN public.storelib_follow_photo(o.published_profile->>'avatar_url', pb, pa) ELSE o.published_profile->>'avatar_url' END), 'null'::jsonb)) ELSE o.published_profile END, settings = CASE WHEN nm AND jsonb_typeof(o.settings) = 'object' THEN jsonb_set(o.settings, '{seo_title}', coalesce(to_jsonb(public.storelib_follow_text(o.settings->>'seo_title', nb, na)), 'null'::jsonb)) ELSE o.settings END WHERE o.owner_id = new.id; UPDATE public.creators c SET display_name = CASE WHEN nm THEN public.storelib_follow_text(c.display_name, nb, na) ELSE c.display_name END, avatar_url = CASE WHEN pm THEN public.storelib_follow_photo(c.avatar_url, pb, pa) ELSE c.avatar_url END WHERE c.user_id = new.id RETURNING c.id INTO cid; IF cid IS NOT NULL THEN UPDATE public.store_builder_configs s SET draft_config = public.storelib_follow_config(s.draft_config, nb, na, pb, pa, nm, pm), published_config = public.storelib_follow_config(s.published_config, nb, na, pb, pa, nm, pm) WHERE s.creator_id = cid; END IF; EXCEPTION WHEN others THEN RAISE WARNING 'profiles_identity_follows skipped for %: %', new.id, sqlerrm; END; RETURN new; END $fn$;
DROP TRIGGER IF EXISTS profiles_identity_follows ON public.profiles;
CREATE TRIGGER profiles_identity_follows AFTER UPDATE OF display_name, avatar_url ON public.profiles FOR EACH ROW WHEN (old.display_name IS DISTINCT FROM new.display_name OR old.avatar_url IS DISTINCT FROM new.avatar_url) EXECUTE FUNCTION public.profiles_identity_follows();
/* One off, for the copies already stale. First: a picture a sign in provider sent, sitting in a OnePage row, goes back to whatever the profile says. This is the Google photo that kept coming back after it was deleted. */
UPDATE public.onepages o SET avatar_url = CASE WHEN public.storelib_provider_photo(o.avatar_url) THEN p.avatar_url ELSE o.avatar_url END, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' AND public.storelib_provider_photo(o.published_profile->>'avatar_url') THEN jsonb_set(o.published_profile, '{avatar_url}', coalesce(to_jsonb(p.avatar_url), 'null'::jsonb)) ELSE o.published_profile END FROM public.profiles p WHERE p.id = o.owner_id AND (public.storelib_provider_photo(o.avatar_url) OR public.storelib_provider_photo(o.published_profile->>'avatar_url'));
/* And in the creator page header, draft and published alike. */
UPDATE public.store_builder_configs s SET draft_config = CASE WHEN public.storelib_provider_photo(s.draft_config#>>'{headerSettings,avatarUrl}') THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN public.storelib_provider_photo(s.published_config#>>'{headerSettings,avatarUrl}') THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND (public.storelib_provider_photo(s.draft_config#>>'{headerSettings,avatarUrl}') OR public.storelib_provider_photo(s.published_config#>>'{headerSettings,avatarUrl}'));
/* Second: creators.display_name and creators.avatar_url are copies of the profile that nothing in the app edits, so they are made equal to it. */
UPDATE public.creators c SET display_name = p.display_name, avatar_url = p.avatar_url FROM public.profiles p WHERE p.id = c.user_id AND (c.display_name IS DISTINCT FROM p.display_name OR c.avatar_url IS DISTINCT FROM p.avatar_url);
/* Third: a Meta title that is only one of the page's own names again. The OnePage SEO card filled its box with the page name and saved what it was showing, so the page carried a second copy of the name that outranked everything the tab title read. It says nothing the page does not already say. */
UPDATE public.onepages o SET settings = jsonb_set(o.settings, '{seo_title}', 'null'::jsonb) FROM public.profiles p WHERE p.id = o.owner_id AND jsonb_typeof(o.settings) = 'object' AND nullif(btrim(coalesce(o.settings->>'seo_title', '')), '') IS NOT NULL AND lower(btrim(o.settings->>'seo_title')) IN (lower(btrim(coalesce(o.title, ''))), lower(btrim(coalesce(o.published_profile->>'title', ''))), lower(btrim(coalesce(p.display_name, ''))));
/* Fourth, and the only statement here that names one account: the OnePage this was reported from (storelib.com/lucadragoste) still showed the name the account was opened with in the phone's bottom bar, from before the trigger above existed, and there is no way to tell from the row alone which of its three name copies holds it. All three are pointed at the profile's name. The page name can be typed again in the OnePage editor at any moment, and from then on it is left alone. A second run changes nothing. */
UPDATE public.onepages o SET title = p.display_name, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(o.published_profile, '{title}', coalesce(to_jsonb(p.display_name), 'null'::jsonb)) ELSE o.published_profile END, settings = CASE WHEN jsonb_typeof(o.settings) = 'object' THEN jsonb_set(o.settings, '{seo_title}', 'null'::jsonb) ELSE o.settings END FROM public.profiles p WHERE p.id = o.owner_id AND lower(coalesce(p.username, '')) = 'lucadragoste' AND (o.title IS DISTINCT FROM p.display_name OR o.published_profile->>'title' IS DISTINCT FROM p.display_name OR nullif(btrim(coalesce(o.settings->>'seo_title', '')), '') IS NOT NULL);
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('44', '44_profile_identity_follows.sql', '7771dde05b9f8d40fba620edf616b7f3ea7cb809e19ddf8bc185addb41a34110') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 45_sites_document_and_questions.sql
/* The website builder's agent: the document a site is, the questions it asked, and the one a run is waiting on. Three changes from 18 to 22 September that this list never carried: sites.document (the pages, sections and theme both editors read and write as one unit, with the index on the revision every write is matched against), site_chat_messages.questions (what the agent asked during a run, kept beside the message so a reload does not lose it), and site_agent_questions (one row per question a run is blocked on, which the answer route updates and the run polls; server only, no policy, so only the service role reaches it). Each skips itself where its table is not there. Adds two columns, one table and three indexes; changes no rows. Needs nothing else. Until it runs, lib/sites/agent and the builder's Ask cannot keep a question, so a reload loses what the agent asked. */
DO $$ BEGIN IF to_regclass('public.sites') IS NOT NULL THEN ALTER TABLE public.sites ADD COLUMN IF NOT EXISTS document jsonb; EXECUTE 'CREATE INDEX IF NOT EXISTS sites_document_revision_idx ON public.sites (((document ->> ''revision'')::int)) WHERE document IS NOT NULL'; EXECUTE 'COMMENT ON COLUMN public.sites.document IS ''Canonical page/section/theme state. The source; site_files rows are rendered from it.'''; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.site_chat_messages') IS NOT NULL THEN ALTER TABLE public.site_chat_messages ADD COLUMN IF NOT EXISTS questions jsonb NOT NULL DEFAULT '[]'::jsonb; EXECUTE 'COMMENT ON COLUMN public.site_chat_messages.questions IS ''What the agent asked the creator during this run: [{id, question, why, suggestions, placeholder}]. Empty when it asked nothing.'''; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.sites') IS NOT NULL THEN CREATE TABLE IF NOT EXISTS public.site_agent_questions (id uuid primary key default gen_random_uuid(), site_id uuid not null references public.sites(id) on delete cascade, run_id uuid not null, question jsonb not null, answer text, skipped boolean not null default false, created_at timestamptz not null default now(), answered_at timestamptz); EXECUTE 'CREATE INDEX IF NOT EXISTS site_agent_questions_pending_idx ON public.site_agent_questions (run_id, created_at desc) WHERE answered_at IS NULL'; EXECUTE 'CREATE INDEX IF NOT EXISTS site_agent_questions_site_idx ON public.site_agent_questions (site_id, created_at desc)'; EXECUTE 'ALTER TABLE public.site_agent_questions ENABLE ROW LEVEL SECURITY'; END IF; END $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('45', '45_sites_document_and_questions.sql', '693295324815980fb8938249e224428d7815e9d9e2e034ad7bddb70ae49989bc') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

-- part 46_email_automations_complete.sql
/* Emails and automations, complete: everything the Emails page, the email composer, the automation builder and the engine read and write, in one part. The contacts (subscribers) with every column the app writes, segments, campaigns with their send bookkeeping, one row per address sent, open and click events, the monthly count, the automations (email_flows) and the older delayed email queue, the engine's runs, jobs and sends with its five functions, started checkouts for the checkout reminder, contact form messages, the rate limit table the test and preview routes count in, and the email-images bucket. Safe on a database that ran none, some or all of parts 09, 10, 13, 21 and 30: every table is created only when missing, every column added only when missing, every check dropped and made again NOT VALID (new rows are checked, old ones are left alone), every unique index made only when no rows break it (a warning names the query to look at otherwise), every policy dropped and made again, every function replaced. Running it twice changes nothing. It deletes no row and changes no row, apart from giving a contact with no unsubscribe token one. The layouts a new email starts from and the automation templates live in the app (lib/email-campaigns/starters.ts, lib/automations/templates.ts), so there is nothing to seed. Needs creators, products, orders and profiles, which every Storelib database has. */
/* 0. What this part stands on. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL OR to_regclass('public.products') IS NULL OR to_regclass('public.orders') IS NULL THEN RAISE EXCEPTION 'public.creators, public.products and public.orders must exist before this part: run the core schema first'; END IF; END $$;
/* One function stamps updated_at on the email tables that have one. Its own name, so no other table's trigger changes. */
CREATE OR REPLACE FUNCTION public.email_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.email_touch_updated_at() FROM PUBLIC;
/* 1. Contacts. One row per creator and address: somebody who joined the list (subscribed), a buyer who did not ask for news (customer), somebody who wrote through a contact form (wrote), or somebody who left or bounced. */
CREATE TABLE IF NOT EXISTS public.subscribers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, email text NOT NULL, name text, source text, source_id uuid, source_detail jsonb, status text DEFAULT 'subscribed', is_active boolean DEFAULT true, consent_text text, consent_timestamp timestamptz DEFAULT now(), unsubscribe_token uuid DEFAULT gen_random_uuid(), tags text[] DEFAULT '{}', metadata jsonb DEFAULT '{}'::jsonb, subscribed_at timestamptz DEFAULT now(), unsubscribed_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now() );
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS name text;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS source text;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS source_id uuid;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS source_detail jsonb;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS status text DEFAULT 'subscribed';
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS is_active boolean DEFAULT true;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS consent_text text;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS consent_timestamp timestamptz DEFAULT now();
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS unsubscribe_token uuid DEFAULT gen_random_uuid();
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS tags text[] DEFAULT '{}';
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS metadata jsonb DEFAULT '{}'::jsonb;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS subscribed_at timestamptz DEFAULT now();
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS unsubscribed_at timestamptz;
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();
ALTER TABLE public.subscribers ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
/* Every unsubscribe link is the contact's token, so every contact has one. The only rows this part writes. */
UPDATE public.subscribers SET unsubscribe_token = gen_random_uuid() WHERE unsubscribe_token IS NULL;
ALTER TABLE public.subscribers DROP CONSTRAINT IF EXISTS subscribers_status_check;
ALTER TABLE public.subscribers ADD CONSTRAINT subscribers_status_check CHECK (status IS NULL OR status IN ('subscribed', 'unsubscribed', 'bounced', 'complained', 'cleaned', 'customer', 'wrote')) NOT VALID;
/* The app names where a contact came from in words it adds to over time ('checkout', 'contact_form', 'profile' and more), so the old two-value list on source is taken off rather than kept in step. */
ALTER TABLE public.subscribers DROP CONSTRAINT IF EXISTS subscribers_source_check;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.subscribers GROUP BY creator_id, lower(email) HAVING count(*) > 1) THEN RAISE WARNING 'subscribers: some creator has the same address twice (in different case), so the one contact per address index was not made. See them with: select creator_id, lower(email), count(*) from public.subscribers group by 1, 2 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX IF NOT EXISTS subscribers_creator_email_lower ON public.subscribers (creator_id, lower(email)); END IF; END $$;
CREATE INDEX IF NOT EXISTS idx_subscribers_creator_id ON public.subscribers (creator_id);
CREATE INDEX IF NOT EXISTS idx_subscribers_creator_status ON public.subscribers (creator_id, status);
CREATE INDEX IF NOT EXISTS idx_subscribers_unsubscribe_token ON public.subscribers (unsubscribe_token);
CREATE INDEX IF NOT EXISTS subscribers_creator_subscribed_at ON public.subscribers (creator_id, subscribed_at DESC);
DROP TRIGGER IF EXISTS subscribers_touch_updated_at ON public.subscribers;
CREATE TRIGGER subscribers_touch_updated_at BEFORE UPDATE ON public.subscribers FOR EACH ROW EXECUTE FUNCTION public.email_touch_updated_at();
ALTER TABLE public.subscribers ENABLE ROW LEVEL SECURITY;
/* Sign-ups arrive through the server (app/api/subscribe and the others use the service role), so the old "anyone can insert" policies, which let anybody with the public key write a contact onto any creator's list, go. A creator reads and edits their own. */
DROP POLICY IF EXISTS "Anyone can subscribe" ON public.subscribers;
DROP POLICY IF EXISTS "Anyone can subscribe via public forms" ON public.subscribers;
DROP POLICY IF EXISTS "Creators can view their subscribers" ON public.subscribers;
DROP POLICY IF EXISTS "Creators can view their own subscribers" ON public.subscribers;
DROP POLICY IF EXISTS "Creators can insert their own subscribers" ON public.subscribers;
DROP POLICY IF EXISTS "Creators can update their own subscribers" ON public.subscribers;
DROP POLICY IF EXISTS "Creators can delete their own subscribers" ON public.subscribers;
CREATE POLICY "Creators can view their own subscribers" ON public.subscribers FOR SELECT TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
CREATE POLICY "Creators can insert their own subscribers" ON public.subscribers FOR INSERT TO authenticated WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
CREATE POLICY "Creators can update their own subscribers" ON public.subscribers FOR UPDATE TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid()))) WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
CREATE POLICY "Creators can delete their own subscribers" ON public.subscribers FOR DELETE TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
REVOKE ALL ON public.subscribers FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.subscribers TO authenticated;
GRANT ALL ON public.subscribers TO service_role;
/* 2. Segments: a saved audience a campaign can go to. */
CREATE TABLE IF NOT EXISTS public.email_segments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL, description text, filters jsonb NOT NULL DEFAULT '{}'::jsonb, subscriber_count integer DEFAULT 0, is_default boolean DEFAULT false, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now() );
ALTER TABLE public.email_segments ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE public.email_segments ADD COLUMN IF NOT EXISTS filters jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.email_segments ADD COLUMN IF NOT EXISTS subscriber_count integer DEFAULT 0;
ALTER TABLE public.email_segments ADD COLUMN IF NOT EXISTS is_default boolean DEFAULT false;
ALTER TABLE public.email_segments ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();
ALTER TABLE public.email_segments ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
CREATE INDEX IF NOT EXISTS idx_email_segments_creator_id ON public.email_segments (creator_id);
DROP TRIGGER IF EXISTS email_segments_touch_updated_at ON public.email_segments;
CREATE TRIGGER email_segments_touch_updated_at BEFORE UPDATE ON public.email_segments FOR EACH ROW EXECUTE FUNCTION public.email_touch_updated_at();
ALTER TABLE public.email_segments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Creators manage their own segments" ON public.email_segments;
CREATE POLICY "Creators manage their own segments" ON public.email_segments FOR ALL TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid()))) WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
REVOKE ALL ON public.email_segments FROM anon;
GRANT ALL ON public.email_segments TO service_role;
/* 3. Campaigns: an email written in the composer, its audience, and where its send is. */
CREATE TABLE IF NOT EXISTS public.email_campaigns ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, subject text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', preview_text text, from_name text, reply_to text, status text NOT NULL DEFAULT 'draft', audience_type text NOT NULL DEFAULT 'all', segment_id uuid REFERENCES public.email_segments(id) ON DELETE SET NULL, audience_count integer DEFAULT 0, scheduled_at timestamptz, sent_at timestamptz, completed_at timestamptz, last_error text, send_idempotency_key text, track_opens boolean NOT NULL DEFAULT true, rendered_html text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS preview_text text;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS from_name text;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS reply_to text;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS audience_type text DEFAULT 'all';
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS segment_id uuid REFERENCES public.email_segments(id) ON DELETE SET NULL;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS audience_count integer DEFAULT 0;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS scheduled_at timestamptz;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS sent_at timestamptz;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS completed_at timestamptz;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS last_error text;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS send_idempotency_key text;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS track_opens boolean NOT NULL DEFAULT true;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS rendered_html text;
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.email_campaigns ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.email_campaigns DROP CONSTRAINT IF EXISTS email_campaigns_status_check;
ALTER TABLE public.email_campaigns ADD CONSTRAINT email_campaigns_status_check CHECK (status IN ('draft', 'scheduled', 'queued', 'sending', 'sent', 'partially_failed', 'failed', 'cancelled')) NOT VALID;
ALTER TABLE public.email_campaigns DROP CONSTRAINT IF EXISTS email_campaigns_audience_type_check;
ALTER TABLE public.email_campaigns ADD CONSTRAINT email_campaigns_audience_type_check CHECK (audience_type IN ('all', 'subscribers', 'customers', 'onepage', 'store_builder', 'segment', 'last_24h', 'last_7days', 'last_30days', 'last_90days')) NOT VALID;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.email_campaigns WHERE send_idempotency_key IS NOT NULL GROUP BY creator_id, send_idempotency_key HAVING count(*) > 1) THEN RAISE WARNING 'email_campaigns: a send key is used twice, so the send once index was not made. See them with: select creator_id, send_idempotency_key, count(*) from public.email_campaigns where send_idempotency_key is not null group by 1, 2 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX IF NOT EXISTS email_campaigns_send_once ON public.email_campaigns (creator_id, send_idempotency_key) WHERE send_idempotency_key IS NOT NULL; END IF; END $$;
CREATE INDEX IF NOT EXISTS idx_email_campaigns_creator ON public.email_campaigns (creator_id);
CREATE INDEX IF NOT EXISTS idx_email_campaigns_creator_status ON public.email_campaigns (creator_id, status);
CREATE INDEX IF NOT EXISTS idx_email_campaigns_sent_at ON public.email_campaigns (sent_at DESC);
CREATE INDEX IF NOT EXISTS email_campaigns_due ON public.email_campaigns (status, scheduled_at);
CREATE INDEX IF NOT EXISTS email_campaigns_active ON public.email_campaigns (status, updated_at);
/* The sending lease is the campaign's updated_at, so every update moves it, to the microsecond. */
CREATE OR REPLACE FUNCTION public.update_email_campaigns_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = clock_timestamp(); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.update_email_campaigns_updated_at() FROM PUBLIC;
DROP TRIGGER IF EXISTS email_campaigns_updated_at ON public.email_campaigns;
CREATE TRIGGER email_campaigns_updated_at BEFORE UPDATE ON public.email_campaigns FOR EACH ROW EXECUTE FUNCTION public.update_email_campaigns_updated_at();
ALTER TABLE public.email_campaigns ENABLE ROW LEVEL SECURITY;
/* Saving, scheduling and sending all go through the server, which checks the body, the audience and the version (app/api/email). From the browser a creator reads their own emails and deletes one that is not being sent; they cannot mark one sent or change one mid-send. */
DROP POLICY IF EXISTS "Users can manage their own campaigns" ON public.email_campaigns;
DROP POLICY IF EXISTS "Creators can view their own campaigns" ON public.email_campaigns;
DROP POLICY IF EXISTS "Creators can insert their own campaigns" ON public.email_campaigns;
DROP POLICY IF EXISTS "Creators can update their own campaigns" ON public.email_campaigns;
DROP POLICY IF EXISTS "Creators can delete their own campaigns" ON public.email_campaigns;
CREATE POLICY "Creators can view their own campaigns" ON public.email_campaigns FOR SELECT TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
CREATE POLICY "Creators can delete their own campaigns" ON public.email_campaigns FOR DELETE TO authenticated USING (status NOT IN ('queued', 'sending') AND creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid())));
REVOKE ALL ON public.email_campaigns FROM anon;
REVOKE INSERT, UPDATE ON public.email_campaigns FROM authenticated;
GRANT SELECT, DELETE ON public.email_campaigns TO authenticated;
GRANT ALL ON public.email_campaigns TO service_role;
/* 4. One row per address a campaign goes to: claimed before its send, retried with a wait, then what happened to it. */
